package com.example.emit.link

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.PipedInputStream
import java.io.PipedOutputStream
import kotlin.concurrent.thread

private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

/** Vectors generated by PC app msms/crypto.py — proves byte-compat with the PC app. */
class LinkCryptoTest {
    private val skPc = ByteArray(32) { it.toByte() }
    private val skPh = ByteArray(32) { (it + 32).toByte() }
    private val na = ByteArray(16) { 0x11 }; private val nb = ByteArray(16) { 0x22 }

    @Test fun vectorsMatchPython() {
        val pc = LinkCrypto.publicKey(skPc); val ph = LinkCrypto.publicKey(skPh)
        assertEquals("8f40c5adb68f25624ae5b214ea767a6ec94d829d3d7b5e1ad1ba6f3e2138285f", hex(pc))
        assertEquals("358072d6365880d1aeea329adf9121383851ed21a28e3b75e965d0d2cd166254", hex(ph))
        assertEquals("dc56c039ba2d418f3f34e7bfc8aad707ea29bd9d657f44123042212b868b6f9a", hex(LinkCrypto.pairCommit(ph, pc, nb)))
        val sh = LinkCrypto.dh(skPh, pc)
        assertEquals("9663aa1da97e848a914a436d04163dfbb89178f107f1b5b77ed3854203382854", hex(sh))
        assertArrayEquals(sh, LinkCrypto.dh(skPc, ph))
        assertEquals("068465", LinkCrypto.pairSas(pc, ph, na, nb))
        val ck = LinkCrypto.pairConfirmKey(sh, pc, ph, na, nb)
        assertEquals("ffa09f6db3b46141047b46cdd45fa46948b83cc4da4212bbdf7babe8d574249b", hex(LinkCrypto.hmac(ck, "pc-ok".toByteArray())))
        val th = LinkCrypto.transcript("""{"t":"hello"}""".toByteArray(), """{"t":"hello_ok"}""".toByteArray())
        assertEquals("4afa573a7b089a4aa0c970c434e199aa5854aab96beb896ec5388ea883371b69", hex(th))
        val e1 = ByteArray(32) { 7 }; val e2 = ByteArray(32) { 9 }
        val (k1, k2) = LinkCrypto.sessionKeys(LinkCrypto.dh(e2, LinkCrypto.publicKey(e1)), sh, th)
        assertEquals("637f0284198cb6290aaf988e0cbbc266667202390a42a7164a1f6b65cbdc4fd3", hex(k1))
        assertEquals("e6e6af7dc8af8428f2a9dbcf113119390421ee48f27a426b65406843d2251332", hex(k2))
        val a = AeadStream(k1)
        assertEquals("389b7cc7968c91874c76a148d3a815f7600d09ad31", hex(a.seal("hello".toByteArray())))
        assertEquals("ce81d40fd1dffacbdb7e3b7a5dbbaffa59d07feb27", hex(a.seal("hello".toByteArray())))
        val r = AeadStream(k1); r.open(AeadStream(k1).seal(byteArrayOf(1)))
    }

    @Test fun aeadRejectsTamperAndReplay() {
        val k = ByteArray(32) { 5 }; val tx = AeadStream(k); val c0 = tx.seal("a".toByteArray())
        val bad = c0.copyOf().also { it[0] = (it[0].toInt() xor 1).toByte() }
        assertThrows(Exception::class.java) { AeadStream(k).open(bad) }
        val rx = AeadStream(k); rx.open(c0)
        assertThrows(Exception::class.java) { rx.open(c0) }
    }

    private class Pipe { val i = PipedInputStream(1 shl 20); val o = PipedOutputStream(i) }

    /** Kotlin mini-initiator mirroring protocol.py, against the real phone responder. */
    @Test fun pairThenSessionRoundTrip() {
        val a = Pipe(); val b = Pipe()
        val phoneIo = FrameIO(a.i, b.o); val pcIo = FrameIO(b.i, a.o)
        var code: String? = null; var paired: PhoneProtocol.PairedPc? = null
        val t = thread { paired = PhoneProtocol.pairResponder(phoneIo, phoneIo.read(), "ph1", "Phone", skPh, { c, _ -> code = c }, { true }) }
        val pubPc = LinkCrypto.publicKey(skPc)
        pcIo.write(json("t" to "pair1", "v" to 1, "pc_id" to "pc1", "name" to "my-pc", "pub" to b64(pubPc)).toString().toByteArray())
        val m2 = JSONObject(String(pcIo.read())); val pubPh = unb64(m2.getString("pub"))
        pcIo.write(json("t" to "pair3", "na" to b64(na)).toString().toByteArray())
        val nb2 = unb64(JSONObject(String(pcIo.read())).getString("nb"))
        assertArrayEquals(unb64(m2.getString("commit")), LinkCrypto.pairCommit(pubPh, pubPc, nb2))
        val ck = LinkCrypto.pairConfirmKey(LinkCrypto.dh(skPc, pubPh), pubPc, pubPh, na, nb2)
        pcIo.write(json("t" to "pair5", "mac" to b64(LinkCrypto.hmac(ck, "pc-ok".toByteArray()))).toString().toByteArray())
        val m6 = JSONObject(String(pcIo.read())); assertEquals("pair6", m6.getString("t")); t.join(2000)
        assertEquals(LinkCrypto.pairSas(pubPc, pubPh, na, nb2), code)
        assertEquals("pc1", paired!!.pcId)

        // session
        val c = Pipe(); val d = Pipe(); val phIo = FrameIO(c.i, d.o); val pIo = FrameIO(d.i, c.o)
        val t2 = thread {
            val (ch, _) = PhoneProtocol.sessionResponder(phIo, phIo.read(), "ph1", skPh, { if (it == "pc1") pubPc else null })
            val req = ch.recv(); ch.send(json("id" to req.getInt("id"), "r" to "pong"))
        }
        val esk = LinkCrypto.genSecret()
        val hello = json("t" to "hello", "v" to 1, "pc_id" to "pc1", "e" to b64(LinkCrypto.publicKey(esk)), "n" to "x").toString().toByteArray()
        pIo.write(hello); val raw2 = pIo.read(); val h2 = JSONObject(String(raw2))
        val (kTx, kRx) = LinkCrypto.sessionKeys(LinkCrypto.dh(esk, unb64(h2.getString("e"))), LinkCrypto.dh(skPc, pubPh), LinkCrypto.transcript(hello, raw2))
        val ch = SecureChannel(pIo, kTx, kRx)
        ch.send(json("t" to "auth", "th" to b64(LinkCrypto.transcript(hello, raw2)))); assertEquals("auth_ok", ch.recv().getString("t"))
        ch.send(json("id" to 1, "m" to "status")); assertEquals("pong", ch.recv().getString("r")); t2.join(2000)
    }

    @Test fun unknownPcRejected() {
        val c = Pipe(); val d = Pipe(); val phIo = FrameIO(c.i, d.o); val pIo = FrameIO(d.i, c.o)
        pIo.write(json("t" to "hello", "v" to 1, "pc_id" to "nope", "e" to b64(LinkCrypto.publicKey(LinkCrypto.genSecret()))).toString().toByteArray())
        assertThrows(ProtocolException::class.java) { PhoneProtocol.sessionResponder(phIo, phIo.read(), "ph1", skPh, { null }) }
        assertEquals("err", JSONObject(String(pIo.read())).getString("t"))
    }
}
